%[text] # BEV Controller - Simulation Case
model_name = "HarnessModel_BEVController";
load_system(model_name) 

BEVController_Basic_params

set_param(model_name + "/BEV Speed Tracking Controller", ReferencedSubsystem = "BEVController_Basic_refsub");

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_BEVController_Simple_refsub");
%[text] 
sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "600");

sim_out = sim(sim_in);

simResultTimetable = extractTimetable(sim_out.logsout);
%[text] 
fig = figure; %[output:27217eb1]
hold on %[output:27217eb1]
grid on %[output:27217eb1]
axis padded %[output:27217eb1]
fig.Position(3:4) = [700 300];  % width height %[output:27217eb1]

plot(simResultTimetable, "Time", "Vehicle speed input kph", LineWidth=2) %[output:27217eb1]
title("Input to controller: Vehicle target speed") %[output:27217eb1]
ylabel("km/h") %[output:27217eb1]
fig = figure; %[output:9537816a]
hold on %[output:9537816a]
grid on %[output:9537816a]
axis padded %[output:9537816a]
fig.Position(3:4) = [700 300];  % width height %[output:9537816a]

plot(simResultTimetable, "Time", "Motor torque command", LineWidth=2) %[output:9537816a]
title("Output from controller: Motor torque command") %[output:9537816a]
ylabel("N*m") %[output:9537816a]
